+    startTransition(async () => {
+      const res = await setUserSuspended({
+        userId: report.targetId!,
+        suspended: true,
+      });
+      if (!res.ok) {
+        toast(t("admin.decisionError"), "alert");
+        return;
+      }
+      announce(
+        t("admin.userSuspended", { name: report.targetName ?? "user" }),
+        true,
+      );
+    });
+  }
+
+  return (
